from collections import deque

def find_contiguous_groups(grid):
    rows, cols = grid.shape
    visited = set()
    groups = []

    for r in range(rows):
        for c in range(cols):
            if grid[r,c] != 5 and (r,c) not in visited:
                # BFS to find connected component
                group = {'value': grid[r,c], 'cells': [], 'count': 0}
                queue = deque([(r,c)])
                visited.add((r,c))
                while queue:
                    cr, cc = queue.popleft()
                    group['cells'].append((cr, cc))
                    group['count'] += 1
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr+dr, cc+dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if grid[nr,nc] == grid[r,c] and (nr,nc) not in visited:
                                visited.add((nr,nc))
                                queue.append((nr,nc))
                groups.append(group)

    return groups

